from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject
from taf.gnb.oam.coam.vdu.schemas.asm_licensed.get_alds_response_v1 import DistName


class M2mLoglinkV1(SchemaObject):
    first_endpoint_dn = SchemaField(name='first_endpoint_dn')
    second_endpoint_dn = SchemaField(name='second_endpoint_dn')
    link_mode_configuration = SchemaField(name='link_mode_configuration')
    link_mode_data = SchemaField(name='link_mode_data')
    link_mode_synchronization = SchemaField(name='link_mode_synchronization')
    link_mode_dc = SchemaField(name='link_mode_dc')
    availability_status = SchemaField(name='availability_status')
    operational_state = SchemaField(name='operational_state')
    dist_names = SchemaField(name='dist_names', not_null=True, klass=DistName)

    def __init__(self, first_endpoint_dn, second_endpoint_dn, link_mode_configuration, link_mode_data,
                 link_mode_synchronization, link_mode_dc, availability_status, operational_state, dist_names):
        self.first_endpoint_dn = first_endpoint_dn
        self.second_endpoint_dn = second_endpoint_dn
        self.link_mode_configuration = link_mode_configuration
        self.link_mode_data = link_mode_data
        self.link_mode_synchronization = link_mode_synchronization
        self.link_mode_dc = link_mode_dc
        self.availability_status = availability_status
        self.operational_state = operational_state
        self.dist_names = dist_names

        super(M2mLoglinkV1, self).__init__()

